    public static readonly string DeferredBlit =
        "FRAG float4 DeferredShadeFrag(VertexData input) : SV_Target\n{\n    float depth = _DepthBuffer.Sample(input.uv);\n \n    if (depth >= 1.0f)\n    {\n        discard;\n    }\n\n    float4 albedoSample = _BlitSource.Sample(input.uv);\n    float2 normalSample = _GBufferNormals.Sample(input.uv);\n    float4 materialSample = _GBufferMaterial.Sample(input.uv);\n\n   Deferred.DeferredReader reader = Deferred.DeferredReader(albedoSample,\n        normalSample,\n        materialSample);\n\n    float3 positionWS = UVDepthToWorld(input.uv, depth);\n\n    Deferred.DeferredShadeData data = reader.Read(positionWS);\n    float3 shadedColor = float3(1, 0, 1);\n\n    // lit\n    if (data.materialIndex == 0)\n    {\n        Lit.BRDF brdf = Lit.BRDF(GetMainLight(positionWS),\n            GetViewDirectionWS(positionWS),\n            data.normalWS,\n            data.albedo,\n            data.smoothness,\n            data.metallic);\n\n        shadedColor = brdf.Shade();\n    }\n    // unlit\n    else if (data.materialIndex == 1)\n    {\n        shadedColor = data.albedo;\n    }\n\n    return float4(shadedColor, 1);\n}";

    public static readonly string SphereVolume =
        "public struct SphereVolume : IBoundingVolume\n{\n    private float3 center;\n    private float radius;\n\n    public __init(float3 _center,\n        float _radius)\n    {\n        center = _center;\n        radius = _radius;\n    }\n\n    public bool IsInside(float3 position,\n        float padding = 0)\n    {\n        float3 diff = position - center;\n        float rPad = radius + padding;\n        return dot(diff, diff) <= (rPad * rPad);\n    }\n\n    public Ray AlignWithVolume(Ray ray)\n    {\n        float3 L = center - ray.GetOrigin();\n        float tca = dot(L, ray.GetDirection());\n\n        float d2 = dot(L, L) - (tca * tca);\n        float r2 = radius * radius;\n\n        if (d2 > r2)\n        {\n            return Ray(ray.GetOrigin(), ray.GetDirection(), 0.0f);\n        }\n\n        float thc = sqrt(r2 - d2);\n\n        float t0 = tca - thc;\n        float t1 = tca + thc;\n\n        if (t1 < 0.0f)\n        {\n            return Ray(ray.GetOrigin(), ray.GetDirection(), 0.0f);\n        }\n\n        float tNear = max(0.0f, t0);\n        float tFar = t1;\n\n        float3 intersect = ray.GetOrigin() + ray.GetDirection() * (tNear + 0.001f);\n\n        float maxLength = max(0.0f, (tFar - tNear) - MAX_LENGTH_BIAS);\n\n        return Ray(intersect, ray.GetDirection(), maxLength);\n    }\n}";

    public static readonly string EllipsoidVolume =
        "public struct EllipsoidVolume : IBoundingVolume\n{\n    private float3 center;\n    private float3x3 worldToLocalRot; \n    private float3 inverseScale;   \n\n    public __init(float3 _center, float3x3 _rotation, float3 _scale)\n    {\n        center = _center;\n        worldToLocalRot = transpose(_rotation);\n        inverseScale = 1.0f / _scale; \n    }\n\n    public bool IsInside(float3 position, float padding = 0)\n    {\n        float3 translatedPos = position - center;\n        float3 rotatedPos = mul(worldToLocalRot, translatedPos);\n        float3 localPos = rotatedPos * inverseScale;\n        \n        float rPad = 1.0f + padding;\n        return dot(localPos, localPos) <= (rPad * rPad);\n    }\n\n    public Ray AlignWithVolume(Ray ray)\n    {\n        float3 translatedOrigin = ray.GetOrigin() - center;\n\n        float3 rotatedOrigin = mul(worldToLocalRot, translatedOrigin);\n        float3 rotatedDir = mul(worldToLocalRot, ray.GetDirection());\n\n        float3 localOrigin = rotatedOrigin * inverseScale;\n        float3 localDir = rotatedDir * inverseScale;\n\n        float a = dot(localDir, localDir);\n        float b = 2.0f * dot(localOrigin, localDir);\n        float c = dot(localOrigin, localOrigin) - 1.0f; \n\n        float discriminant = (b * b) - (4.0f * a * c);\n\n        if (discriminant < 0.0f)\n        {\n            return Ray(ray.GetOrigin(), ray.GetDirection(), 0.0f);\n        }\n\n        float sqrtDisc = sqrt(discriminant);\n        float t0 = (-b - sqrtDisc) / (2.0f * a);\n        float t1 = (-b + sqrtDisc) / (2.0f * a);\n\n        if (t1 < 0.0f)\n        {\n            return Ray(ray.GetOrigin(), ray.GetDirection(), 0.0f);\n        }\n\n        float tNear = max(0.0f, t0);\n        float tFar = t1;\n\n        float3 intersect = ray.GetOrigin() + ray.GetDirection() * (tNear + 0.001f);\n        float maxLength = max(0.0f, (tFar - tNear) - MAX_LENGTH_BIAS);\n\n        return Ray(intersect, ray.GetDirection(), maxLength);\n    }\n}\n";

    public static readonly string AABBVolume =
        "public struct AABB : IBoundingVolume\n{\n    private float3 center;\n    private float3 extents;\n\n    public __init(float3 _center, float3 size)\n    {\n        center = _center;\n        extents = size * 0.5f;\n    }\n\n    public bool IsInside(float3 position, float padding = 0)\n    {\n        float3 dist = abs(position - center);\n        return all(dist <= extents + padding);\n    }\n\n    public Ray AlignWithVolume(Ray ray)\n    {\n        float3 directionRcp = rcp(ray.GetDirection());\n        float3 minPoint = center - extents;\n        float3 maxPoint = center + extents; \n\n        float3 t0 = (minPoint - ray.GetOrigin()) * directionRcp;\n        float3 t1 = (maxPoint - ray.GetOrigin()) * directionRcp;\n\n        float3 tMin = min(t0, t1);\n        float3 tMax = max(t0, t1);\n\n        float tNear = max(max(tMin.x, tMin.y), tMin.z);\n        tNear = max(0.0f, tNear);\n        float tFar = min(min(tMax.x, tMax.y), tMax.z);\n\n        float3 intersect = ray.GetOrigin() + ray.GetDirection() * (tNear + 0.001f);\n\n        float maxLength = max(0.0f, (tFar - tNear) - MAX_LENGTH_BIAS);\n\n        return Ray(intersect, ray.GetDirection(), maxLength);\n    }\n}";

    public static readonly string OBBVolume =
        "public struct OBB : IBoundingVolume\n{\n    private float3 center;\n    private float3 extents;\n    private float3x3 worldToLocalRot;\n\n    public __init(float3 _center, float3 size, float3x3 _rotation)\n    {\n        center = _center;\n        extents = size * 0.5f;\n        worldToLocalRot = transpose(_rotation); \n    }\n\n    public bool IsInside(float3 position, float padding = 0)\n    {\n        float3 localPos = mul(worldToLocalRot, position - center);\n        float3 dist = abs(localPos);\n        return all(dist <= extents + padding);\n    }\n\n    public Ray AlignWithVolume(Ray ray)\n    {\n        if (IsInside(ray.GetOrigin()))\n        {\n            return ray;\n        }\n\n        float3 localOrigin = mul(worldToLocalRot, ray.GetOrigin() - center);\n        float3 localDir = mul(worldToLocalRot, ray.GetDirection());\n        \n        float3 directionRcp = rcp(localDir);\n        float3 minPoint = -extents;\n        float3 maxPoint = extents; \n\n        float3 t0 = (minPoint - localOrigin) * directionRcp;\n        float3 t1 = (maxPoint - localOrigin) * directionRcp;\n\n        float3 tMin = min(t0, t1);\n        float3 tMax = max(t0, t1);\n\n        float tNear = max(max(tMin.x, tMin.y), tMin.z);\n        tNear = max(0.0f, tNear);\n        float tFar = min(min(tMax.x, tMax.y), tMax.z);\n\n        float3 intersect = ray.GetOrigin() + ray.GetDirection() * (tNear + 0.001f);\n        \n        float maxLength = max(0.0f, (tFar - tNear) - MAX_LENGTH_BIAS);\n\n        return Ray(intersect, ray.GetDirection(), maxLength);\n    }\n}";

    public static readonly string WorldToDepth =
        "float WorldPosToDepth(float3 positionWS)\n{\n    float4 hitClipPos = mul(_ViewProjMat, float4(positionWS, 1.0));\n    return hitClipPos.z / hitClipPos.w;\n}";

    public static readonly string SDFNormal =
        "float3 GetNormal(MarchData data)\n{\n    float eps = NORMAL_EPS + data.TotalDistance * NORMAL_EPS;\n\n    MarchData a = data;\n    MarchData b = data;\n\n    a.Position = data.Position + float3(eps, 0, 0);\n    b.Position = data.Position - float3(eps, 0, 0);\n    float dx = Evaluate(a) - Evaluate(b);\n\n    a.Position = data.Position + float3(0, eps, 0);\n    b.Position = data.Position - float3(0, eps, 0);\n    float dy = Evaluate(a) - Evaluate(b);\n\n    a.Position = data.Position + float3(0, 0, eps);\n    b.Position = data.Position - float3(0, 0, eps);\n    float dz = Evaluate(a) - Evaluate(b);\n    \n    return normalize(float3(dx, dy, dz));\n}";

    public static readonly string HLSLLayout =
        "// this is the implementation file\n\n#ifndef BIKE_VEHICLE_INCLUDED\n#define BIKE_VEHICLE_INCLUDED\n\n#define WHEELS float3(1.0f, 1.0f, 1.0f)\n#define FRAME float3(1.0f, 1.0f, 1.0f)\n\n\n// implementation functions\nfloat3 CalculateBikeWheels(float3 position)\n{\n    return WHEELS + position;\n}\n\nfloat3 CalculateBikeFrame(float3 position)\n{\n    return FRAME + position;\n}\n\n\n// define the macros that vehicle layout requires\n#define CALC_WHEELS CalculateBikeWheels\n#define CALC_FRAME CalculateBikeFrame\n\n#include \"VehicleLayout.hlsl\"\n\n#endif\n\n// this is the layout file\n\n#ifndef VEHICLE_LAYOUT_INCLUDED\n#define VEHICLE_LAYOUT_INCLUDED\n\n\n// our abstract function with unimplemented macros\nfloat3 BuildVehicle(float3 position)\n{\n    return CALC_WHEELS(position) + CALC_FRAME(position);\n}\n\n#endif";

    public static readonly string SDFLayout =
        "static float NORMAL_EPS = 0.001f;\n\npublic struct MarchData\n{\n    public float3 Position;\n    public float TotalDistance;\n    public float3 Direction;\n    public float LocalDistance;\n}\n\npublic interface SDF\n{\n    public float Evaluate(MarchData data);\n\n    public float3 GetNormal(MarchData data)\n    {\n        float eps = NORMAL_EPS + data.TotalDistance * NORMAL_EPS;\n\n        MarchData a = data;\n        MarchData b = data;\n\n        a.Position = data.Position + float3(eps, 0, 0);\n        b.Position = data.Position - float3(eps, 0, 0);\n        float dx = Evaluate(a) - Evaluate(b);\n\n        a.Position = data.Position + float3(0, eps, 0);\n        b.Position = data.Position - float3(0, eps, 0);\n        float dy = Evaluate(a) - Evaluate(b);\n\n        a.Position = data.Position + float3(0, 0, eps);\n        b.Position = data.Position - float3(0, 0, eps);\n        float dz = Evaluate(a) - Evaluate(b);\n        \n        return normalize(float3(dx, dy, dz));\n    }\n}";

    public static readonly string SphereTracingLoop =
        "Import SDF;\n\npublic struct TraceResult\n{\n    public bool Hit;\n    public float TotalDistance;\n    public int TotalSteps;\n    public float3 Position;\n    public float3 Normal;\n    public int MaterialIndex;\n\n    public __init(float3 startPos)\n    {\n        Hit = false;\n        TotalDistance = 0;\n        TotalSteps = 0;\n        Position = startPos;\n        Normal = 0;\n        MaterialIndex = 0;\n    }\n}\n\npublic struct SphereTracer<T : SDF.SDF>\n{\n    private T sdf;\n    private Ray ray;\n\n    public __init(T _sdf, Ray _ray)\n    {\n        sdf = _sdf;\n        ray = _ray;\n    }\n\n    public TraceResult Trace()\n    {\n        TraceResult result = TraceResult(ray.GetOrigin());\n        SDF.MarchData marchData;\n        marchData.Direction = ray.GetDirection();\n        float invLength = rcp(ray.GetMaxLength());\n        \n        for (int i = 0; i < MAX_STEPS; i++)\n        {\n            marchData.Position = result.Position;\n            marchData.TotalDistance = result.TotalDistance;\n            marchData.LocalDistance = result.TotalDistance * invLength;\n\n            float dist = sdf.Evaluate(marchData);\n\n            if (dist < DST_EPS)\n            {\n                result.Hit = true;\n                result.TotalSteps = i;\n                result.Normal = sdf.GetNormal(marchData);\n                break;\n            }\n\n            result.Position += dist * ray.GetDirection();\n            result.TotalDistance += dist;\n\n            if (result.TotalDistance > ray.GetMaxLength())\n            {\n                break;\n            }\n        }\n\n        return result;\n    }\n}";

    public static readonly string BoundingVolumeLayout =
        "public interface IBoundingVolume\n{\n    public bool IsInside(float3 position, float padding = 0);\n    public Ray AlignWithVolume(Ray ray);\n\n    public bool ShouldMarch(float3 position, bool isFrontFace, float nearPlane)\n    {\n        bool isCameraInside = IsInside(position, nearPlane * SHOULD_MARCH_SCALAR);\n        return isCameraInside != isFrontFace; \n    }\n}";

    public static readonly string RayAligner =
        "public struct RayAligner<TVolume : IBoundingVolume>\n{\n    private TVolume volume;\n    private Ray ray;\n    private bool isFrontFace;\n\n    public __init(TVolume _volume,\n        bool _isFrontFace,\n        float3 _viewDirWS)\n    {\n        volume = _volume;\n        isFrontFace = _isFrontFace;\n        ray = Ray(_CameraPos, _viewDirWS, _ZBufferParams.x);\n    }\n\n    [mutating]\n    public Ray GetAlignedRay()\n    {\n        if(!volume.ShouldMarch(_CameraPos, isFrontFace, _ZBufferParams.x))\n        {\n            discard;\n        }\n\n        ray = volume.AlignWithVolume(ray);\n\n        if (ray.GetMaxLength() < 1e-3f)\n        {\n            discard;\n        }\n\n        return ray;\n    }\n}";

    public static readonly string PlanetSDF =
        "public struct Planet : SDF.SDF\n{\n    private float3 center;\n    private float scale;\n    private float invScale;\n    private float radius;\n    private float[5] hash;\n    private float3 normal;\n    private float3x3 basis;\n    private float4[4] colors;\n\n    public __init(float3 _center, \n        float _scale,\n        int _seed,\n        float4[4] _colors)\n    {\n        center = _center;\n        scale = _scale;\n        colors = _colors;\n        invScale = rcp(scale);\n        radius = 0.48f;\n\n        [unroll(5)]\n        for (int i = 0; i < 5; i++)\n        {\n            hash[i] = Noise.Functions.IntegerHash(_seed + PLANET_SEEDS[i]);\n        }\n\n        normal = normalize(float3(hash[2] - 0.5f, hash[3] - 0.5f, hash[4] - 0.5f));\n        basis = Math.GetOrthogonalBasis(normal);\n    }\n\n    public float Evaluate(SDF.MarchData data)\n    {\n        float3 localPos = (data.Position - center) * invScale;\n        float planetDist = Planet(localPos);\n        planetDist *= scale;\n        return planetDist;\n    }\n\n    private float Planet(float3 localPos)\n    {\n        float base = GetBase(localPos);\n        float ring = GetRing(localPos);\n\n        return SDF.Functions.Union(base, ring);\n    }\n\n    private float GetBase(float3 localPos)\n    {\n        float baseDist = SDF.Functions.Sphere(localPos, radius);\n        return baseDist;\n    }\n\n    private float GetRing(float3 localPos)\n    {\n        float plane = SDF.Functions.Box(mul(basis, localPos), float3(100, PLANET_RING_THICKNESS, 100));\n\n        float innerRingSize = lerp(INNER_RING_SIZE.x, INNER_RING_SIZE.y, hash[1]);\n        float outerRingSize = lerp(OUTER_RING_SIZE.x, OUTER_RING_SIZE.y, hash[0]);\n        outerRingSize = outerRingSize - innerRingSize < MIN_RING_THICKNESS ? 0 : outerRingSize;\n\n        float outerShape = SDF.Functions.Sphere(localPos, radius * outerRingSize);\n        SDF.FieldOut ringOuter = SDF.Functions.Intersection(plane, outerShape);\n        float innerShape = SDF.Functions.Sphere(localPos, radius * innerRingSize);\n\n        float ringDist = SDF.Functions.Subtraction(innerShape, ringOuter);\n        return ringDist;\n    }\n}\n";

    public static readonly string SphereTracingFragment =
        "SphereTracing.OBB volume = SphereTracing.OBB(center, \n    scale * 2.0f, \n    (float3x3)transform.objToWorldDirMat);\n\nSphereTracing.RayAligner<SphereTracing.OBB> rayAligner = SphereTracing.RayAligner<SphereTracing.OBB>(\n    volume,\n    isFrontFace,\n    viewDirWS);\n\nSphereTracing.Ray ray = rayAligner.GetAlignedRay();\n\nGalaxy.Planet planetSDF = Galaxy.Planet(transformCenter, \n    materialData.Scale,\n    materialData.Id,\n    { materialData.ColorA, materialData.ColorB, materialData.ColorC, materialData.ColorD });\n\nSphereTracing.SphereTracer<Galaxy.Planet> tracer = SphereTracing.SphereTracer<Galaxy.Planet>(\n    planetSDF,\n    ray);\n\nSphereTracing.TraceResult result = tracer.Trace();\n\nif (!result.Hit)\n    discard;";
